+}
+
+/// C at 6000 deg/min feed, 12000 deg/min rapid: the work turns at most
+/// 12000 / 360 = 33.3 rpm.
+const RATED: (Option<f64>, Option<f64>) = (Some(6000.0), Some(12_000.0));
